=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to react on brake increase request triggeres and to determine 
   the required brake increase gradient and target*/

// hint : hysterese einbauen.

// Reset of internals
CsmjBrkInc    = 0;
CsmHoldBrkIncActive = false;
CsmHoldBrkIncATarLimit = 0;
CsmHoldBrkIncActvforEmergency = false;

// check requests
IncToCSMRequested = (CsmHoldBrkIncToCSMComfortEnabled
						|| CsmHoldBrkIncToCSMPerformanceEnabled
						|| CsmHoldBrkIncToCSMEmergencyEnabled
						|| CsmHoldBrkIncToCSMFcnSpecificEnabled)
					&& (CsmHoldBrkHoldReqActive > 0);

IncToFCNRequested = (CsmHoldBrkIncToFCNComfortEnabled
						|| CsmHoldBrkIncToFCNPerformanceEnabled
						|| CsmHoldBrkIncToFCNEmergencyEnabled
						|| CsmHoldBrkIncToFCNFcnSpecificEnabled)
					&& (CsmHoldBrkHoldReqActive > 0);

// Get value for volume flow (NVH) limitation
if(FS_CSM_HoldConsiderNPumo)
{
	CSM_nPumo2q.calc(C_CSM_BrakeNPumoRef);
	q_MaxBrkIncRefBrake = CSM_nPumo2q.qBrake();
	CSM_nPumo2q.calc(C_CSM_BrkIncNPumoMaxComfort);
	q_BrkIncComfort = CSM_nPumo2q.qBrake();
	CSM_nPumo2q.calc(C_CSM_BrkIncNPumoMaxPerformance);
	q_BrkIncPerformance = CSM_nPumo2q.qBrake();
	CSM_nPumo2q.calc(C_CSM_BrkIncNPumoMaxEmergency);
	q_BrkIncEmergency = CSM_nPumo2q.qBrake();
}
else
{
	q_MaxBrkIncRefBrake = C_CSM_BrakeQMaxBrkIncRef;
	q_BrkIncComfort = C_CSM_BrkIncQMaxComfort;
	q_BrkIncPerformance = C_CSM_BrkIncQMaxPerformance;
	q_BrkIncEmergency = C_CSM_BrkIncQMaxEmergency;
}


// In case CSM level already reached the related increase gradients won't be considered
if(		CsmHoldIncToCSMLevelReached == true
	||	CsmHoldBrkHoldReqActive == 0)
{
	CsmjBrkInc = CsmjBrkInc;
	CsmHoldBrkIncActive = CsmHoldBrkIncActive;
	BrkIncByDrvOffTrqBal = false;
}
else
{
	// if comfort gradient enabled consider related gradient
	if(CsmHoldBrkIncToCSMComfortEnabled == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncComfort/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjComfort).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldABrkThrMax.min(CsmHoldBrkIncATarLimit);
	}
	
	// Performance gradient in case of torque balanced drive off
	if(		(	 	CsmHoldDrvOffTrqBalActiveK1 == true
				&&	CsmHoldDrvOffTrqBalActive == false
				&&	(	CsmDrvOffTrqBalModeK1 == CSMDrvOffTrqBalMode_SensitiveWithBrkInc
					||	CsmDrvOffTrqBalModeK1 == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc))
			||	BrkIncByDrvOffTrqBal == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncPerformance/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjPerformance).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldABrkThrMax.min(CsmHoldBrkIncATarLimit);
		BrkIncByDrvOffTrqBal = true;
	}else
	{
		BrkIncByDrvOffTrqBal = false;
	}
	
	// if performance gradient enabled consider related gradient
	if(CsmHoldBrkIncToCSMPerformanceEnabled == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncPerformance/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjPerformance).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldABrkThrMax.min(CsmHoldBrkIncATarLimit);
	}
	
	// if emergency gradient enabled consider related gradient
	if(CsmHoldBrkIncToCSMEmergencyEnabled == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncEmergency/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjEmergency).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldABrkThrMax.min(CsmHoldBrkIncATarLimit);
		CsmHoldBrkIncActvforEmergency = true;
	}
	
	// if function specific gradient enabled consider related gradient
	if(CsmHoldBrkIncToCSMFcnSpecificEnabled == true)
	{
		CsmjBrkInc = ((CsmHoldBrkIncToCSMFcnGrad).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldABrkThrMax.min(CsmHoldBrkIncATarLimit);
	}
}

// In case Function level already reached the related increase gradients won't be considered
if(		CsmHoldBrkIncToFCNLevelReached == true
	||	CsmHoldBrkHoldReqActive == 0)
{
	CsmjBrkInc = CsmjBrkInc;
	CsmHoldBrkIncActive = CsmHoldBrkIncActive;
}else
{
	// if comfort gradient enabled consider related gradient
	if(CsmHoldBrkIncToFCNComfortEnabled == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncComfort/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjComfort).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldBrkIncToFCNATar.min(CsmHoldBrkIncATarLimit);
	}
		
	// if performance gradient enabled consider related gradient
	if(CsmHoldBrkIncToFCNPerformanceEnabled == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncPerformance/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjPerformance).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldBrkIncToFCNATar.min(CsmHoldBrkIncATarLimit);
	}
	
	// if emergency gradient enabled consider related gradient
	if(CsmHoldBrkIncToFCNEmergencyEnabled == true)
	{
		CsmjBrkIncLimited = JMinRef * q_BrkIncEmergency/q_MaxBrkIncRefBrake;
		temp_CsmjBrkInc = (C_CSM_BrkIncjEmergency).max(CsmjBrkIncLimited);
		CsmjBrkInc = ((temp_CsmjBrkInc).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldBrkIncToFCNATar.min(CsmHoldBrkIncATarLimit);
		CsmHoldBrkIncActvforEmergency = true;
	}
		
	// if function specific gradient enabled consider related gradient
	if(CsmHoldBrkIncToFCNFcnSpecificEnabled == true)
	{
		CsmjBrkInc = ((CsmHoldBrkIncToFCNFcnGrad).min(CsmjBrkInc)).min(0);
		CsmHoldBrkIncActive = true;
		CsmHoldBrkIncATarLimit = CsmHoldBrkIncToFCNATar.min(CsmHoldBrkIncATarLimit);
	}
}

//Determine Target Brake Request
if(CsmHoldBrkIncActive == true)
{
	if (OperationPointConsiderSyst == true
		&&	CsmHoldBrkIncActiveK1 == false)
	{
		CsmHoldBrkIncATarBrk = ((CsmHoldATarBrk + CsmjBrkInc * CycleTime).min(ADrv)).min(CsmAActConfirmedReq).min(CsmABrkSys); // op-fix: system condition added
	}
	else if(CsmHoldBrkIncActiveK1 == false)
	{
		CsmHoldBrkIncATarBrk = ((CsmHoldATarBrk + CsmjBrkInc * CycleTime).min(ADrv)).min(CsmAActConfirmedReq);
	}else
	{
		CsmHoldBrkIncATarBrk = CsmHoldBrkIncATarBrk + CsmjBrkInc * CycleTime; //op-fix: removed: .min(ADrv)
	}
	CsmHoldBrkIncATarBrk = CsmHoldBrkIncATarBrk.max(CsmHoldBrkIncATarLimit).max(CsmHoldATarThermLimit);
}else
{
	CsmHoldBrkIncATarBrk = 0;
}

// check thermal limit:
CsmThermalLimitReached = (CsmHoldBrkIncATarBrk <= CsmHoldATarThermLimit);

// Check which level is already reached
if	((	(CsmHoldBrkIncATarBrk <= CsmHoldABrkThrMax) 		// CSM target level reached
		&&	(CsmHoldABrkThrMax >= CsmHoldABrkThrMaxK1)		// no increasing (negative) change of target level detected
		&&	(IncToCSMRequested == true))
	||	(CsmThermalLimitReached))						// thermal limit reached
{
	CsmHoldIncToCSMLevelReached = true;
}
else if (	(CsmHoldIncToCSMLevelReached)						//limit already reached
			&& (IncToCSMRequested == true)
			&& ((CsmHoldABrkThrMax >= CsmHoldABrkThrMaxK1)			//keep reached information in case no further target increase
				||(CsmHoldABrkThrMax < CsmHoldATarThermLimit))		//keep reached information if target is above thermal limit.
		)
{
	CsmHoldIncToCSMLevelReached = CsmHoldIncToCSMLevelReached;
}		
else
{
	CsmHoldIncToCSMLevelReached = false;
}

if	((	(CsmHoldBrkIncATarBrk <= CsmHoldBrkIncToFCNATar)			// FCN target level reached
		&&	(CsmHoldBrkIncToFCNATar >= CsmHoldBrkIncToFCNATarK1)	// no increasing (negative) change of target level detected
		&&	(IncToFCNRequested == true))
	||	(CsmThermalLimitReached))								// thermal limit reached
{
	CsmHoldBrkIncToFCNLevelReached = true;
}
else if (	(CsmHoldBrkIncToFCNLevelReached)							//limit already reached
			&& (IncToFCNRequested == true)
			&& ((CsmHoldBrkIncToFCNATar >= CsmHoldBrkIncToFCNATarK1)		//keep reached information in case no further target increase
				||(CsmHoldBrkIncToFCNATar < CsmHoldATarThermLimit))			//keep reached information if target is above thermal limit.
		)
{
	CsmHoldBrkIncToFCNLevelReached = CsmHoldBrkIncToFCNLevelReached;
}
else
{
	CsmHoldBrkIncToFCNLevelReached = false;
}

// provide feedback to requesting functions about target reached
	// set tgt reached once increase is not active anymore (expectation that function does not aboard request)
	setLvlReached = CsmHoldBrkIncActiveK1 && !CsmHoldBrkIncActive;
	
	// reset tgt reached either when increase becomes active again or after defined filter time
	FilterLvlReached.calc(setLvlReached, 0.1);
	resetLvlReached = (CsmHoldBrkIncActive && !CsmHoldBrkIncActiveK1) || (!setLvlReached && !FilterLvlReached.Out());
	
	// result
	CsmIncTgtReachedRS.calc(resetLvlReached, setLvlReached);
	CsmIncTgtReached = CsmIncTgtReachedRS.Q();

// define k1 for next cycle
CsmHoldDrvOffTrqBalActiveK1 = CsmHoldDrvOffTrqBalActive;
CsmDrvOffTrqBalModeK1 = CsmDrvOffTrqBalMode;
CsmHoldBrkIncActiveK1 = CsmHoldBrkIncActive;
CsmHoldABrkThrMaxK1 = CsmHoldABrkThrMax;
CsmHoldBrkIncToFCNATarK1 = CsmHoldBrkIncToFCNATar;


=== Method: CsmHoldBrkIncActive (AbstractMethod) ===
return CsmHoldBrkIncActive;


=== Method: CsmHoldBrkIncATarBrk (AbstractMethod) ===
return CsmHoldBrkIncATarBrk;


=== Method: CsmHoldBrkIncEmergencyActive (AbstractMethod) ===
return CsmHoldBrkIncActvforEmergency;


=== Method: CsmIncTgtReached (AbstractMethod) ===
return CsmIncTgtReached;
